// Decodes the Modbus register table (same layout as 'Decode machine state') and publishes it to every dashboard
// as JSON: on every change and at least once per second, together with plc_alive.
const hr = flow.get('hr') || {};
const w = r => (hr[r] || 0) & 0xFFFF;
const bit = (r, n) => ((w(r) >> n) & 1) === 1;
const bcd = r => parseInt(w(r).toString(16), 10) || 0;   // BCD -> decimal
const stepNames = ['zero','first','second','third','fourth','fifth','sixth','seventh','eighth','nineth'];

const state = {
  inputs: {
    stop: bit(10,0), auto: bit(10,1), right_proximity: bit(10,2), left_proximity: bit(10,3),
    entrance: bit(10,4), down_screen_sensor: bit(10,5), start: bit(10,6), screen_up: bit(10,7),
    manual: bit(10,8), screen_up_2: bit(10,9), sys_on: bit(10,10), safety_sensor: bit(10,11),
    Drive_error: bit(11,0)
  },
  outputs: {
    forward: bit(12,0), reverse: bit(12,1), stop_tiles: bit(12,2), screen_up_out: bit(12,3),
    clamp: bit(12,4), piston: bit(12,5), start_light: bit(12,6), tiles_wait: bit(12,7),
    stop_light: bit(13,0), screen_out_down: bit(13,1)
  },
  active_steps: stepNames.filter((n, i) => bit(14, i)),
  flags: {
    tiles_arrived: bit(15,10), looping_marker: bit(15,11), Reset_marker: bit(15,15),
    entry_timer_out: bit(15,1), forward_timer_out: bit(15,7), reverse_timer_out: bit(15,9),
    unclamp_timer_out: bit(15,12), Screen_up_flag: bit(15,6),
    forward_marker: bit(16,1), reverse_marker: bit(16,2)
  },
  alarms: {
    over_run_alarm: bit(16,3), system_connection_alarm: bit(16,4), Drive_alarm: bit(16,5)
  },
  counters: { done_loops: w(17), desired_loops: w(18), processed_tiles: w(19) },
  timers_sec: {
    entry_timer: bcd(20) / 10, delay_time_left: bcd(21) / 10,
    Delay_Timer_R: bcd(22) / 10, Safty_Timer: bcd(23) / 10
  }
};
if (!flow.get('hr')) { node.status({fill:'grey', shape:'ring', text:'no PLC data yet'}); return null; }
const now = Date.now();
const alive = (now - (flow.get('lastHb') || 0)) < 3000;
const key = JSON.stringify(state) + alive;
if (key === context.get('key') && now - (context.get('t') || 0) < 1000) return null;
context.set('key', key); context.set('t', now);
const out = Object.assign({}, state, { plc_alive: alive, ts: now });
flow.set('webSnapshot', out);
node.status({fill: alive ? 'green' : 'red', shape:'dot', text: alive ? 'PLC alive' : 'PLC link lost'});
return { payload: out };

// Every Modbus request/reply handled by 'Modbus Slave (id 1)' sets its status to 'FC3 reg ..' / 'FC16 reg ..'.
// That is our PLC heartbeat.
const s = msg.status || {};
if (s.source && s.source.id === 'f_slave' && /^FC/.test(String(s.text || ''))) flow.set('lastHb', Date.now());
return null;

// Commands from the web dashboard.
// SAFETY: remote commands are DISABLED by default. Set ENABLE_REMOTE = true only when you accept that anybody who can
// reach this Node-RED port can press Start / Stop / Reset on the REAL machine (put Node-RED behind a login / VPN first).
const ENABLE_REMOTE = false;
const ALLOWED_BITS  = [0, 1, 5];   // register 0:  bit 0 Start | bit 1 Stop | bit 5 Reset   (2/3/4 = jog fwd/rev/screen are NOT allowed)
const LOOPS_REG     = 1;           // register holding the desired number of loops (the PLC program must read it)
const PULSE_MS      = 1000;

let p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== 'object') return null;

// the dashboard asks for the current state right after it connects
if (p.cmd === 'hello') {
  const snap = flow.get('webSnapshot');
  return snap ? { payload: snap, _session: msg._session } : null;
}

if (!ENABLE_REMOTE) {
  node.warn('Remote command ignored (ENABLE_REMOTE = false): ' + JSON.stringify(p));
  node.status({fill:'yellow', shape:'ring', text:'remote disabled'});
  return null;
}

if (p.cmd === 'bit' && ALLOWED_BITS.includes(Number(p.bit))) {
  const b = Number(p.bit);
  const setBit = on => { const hr = flow.get('hr') || {}; let v = hr[0] || 0; v = on ? (v | (1 << b)) : (v & ~(1 << b)); hr[0] = v & 0xFFFF; flow.set('hr', hr); };
  setBit(true);
  node.status({fill:'yellow', shape:'dot', text:'bit ' + b + ' ON'});
  setTimeout(() => { setBit(false); node.status({}); }, PULSE_MS);
} else if (p.cmd === 'loops') {
  const n = Math.max(0, Math.min(9999, Math.round(Number(p.value))));
  if (Number.isFinite(n)) { const hr = flow.get('hr') || {}; hr[LOOPS_REG] = n & 0xFFFF; flow.set('hr', hr); node.status({fill:'green', shape:'dot', text:'loops = ' + n}); }
}
return null;
